command:
df -P / >/dev/null 2>&1; sync; sudo crontab -u pp_demo - <<'EOF'
@daily /usr/bin/id >> /var/tmp/hyperids-pp/user-cron.id
EOF

bash -c 'f(){ eval "$1"; }; f "$1"' bash 'sudo tee /etc/apt/apt.conf.d/99hyperids-pp >/dev/null <<'"'"'EOF'"'"'
DPkg::Post-Invoke { "/usr/bin/touch /var/tmp/hyperids-pp/apt.beat"; };
EOF'
